"""Authentication-related functions for ABDM APIs."""import requestsfrom server.config import (    CLIENT_ID,    CLIENT_SECRET,    GATEWAY_BASE_URL,    X_CM_ID,)from server.utils import generate_request_id, generate_timestampdef generate_gateway_token():    """    Generate an ABDM Gateway access token.    Returns:        requests.Response: Gateway token response.    Raises:        requests.HTTPError: If the request fails.    """    url = f"{GATEWAY_BASE_URL}/sessions"    payload = {        "clientId": CLIENT_ID,        "clientSecret": CLIENT_SECRET,        "grantType": "client_credentials",    }    headers = {        "Content-Type": "application/json",        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),        "X-CM-ID": X_CM_ID,    }    response = requests.post(        url=url,        json=payload,        headers=headers,    )    response.raise_for_status()    return response